const extract = (r: any): any[] => {
  if (Array.isArray(r)) return r;
  if (r && typeof r === "object") {
    for (const k of ["items", "issues", "data", "results"]) {
      if (Array.isArray((r as any)[k])) return (r as any)[k];
    }
  }
  return [];
};

const perPage: number[] = [];
const seen = new Set<number>();
let dupes = 0;
let prCount = 0;
let total = 0;
for (let page = 1; page <= 200; page++) {
  const r = await tools.list_issues({ repo: "acme/cli", state: "closed", page });
  const items = extract(r);
  perPage.push(items.length);
  for (const it of items as any[]) {
    if (seen.has(it.number)) dupes++;
    seen.add(it.number);
    if (it.pull_request) prCount++;
  }
  total += items.length;
  if (items.length === 0) break;
}
return { perPage, total, unique: seen.size, dupes, prCount };
